theory.example:
int copy_value(const int& value) {
  return value;
}

int prepare() {
  int reading = 18;
  return copy_value(reading);
}
// copy_value заимствует живой reading только на время вызова.
// prepare возвращает самостоятельный int, а не ссылку на reading.

references.example:
int number = 18;
const int* view = &number;
number = 25;
// Пока number жив, *view читает тот же объект и даст 25.
// Копии указателя не являются отдельными копиями number.
